import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = next();
        for (int i = 0; i < n; i++) b[i] = next();
        Arrays.sort(a);
        Arrays.sort(b);
        // The smallest a that beats the smallest unmatched b takes it; an a that cannot is skipped.
        int j = 0;
        for (long v : a)
            if (j < n && v > b[j]) j++;
        System.out.println(j);
    }
